.ds-btn{
  font: inherit;
  font-size: 14px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 13px;
  border-radius: var(--r-sm, 4px);
  border: 0.5px solid transparent;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition: background 250ms cubic-bezier(0.16, 1, 0.3, 1), border-color 250ms cubic-bezier(0.16, 1, 0.3, 1), color 250ms cubic-bezier(0.16, 1, 0.3, 1), transform 250ms cubic-bezier(0.16, 1, 0.3, 1);
  white-space: nowrap;
}
.ds-btn:active{ transform: translateY(.5px); }
.ds-btn-primary{
  background: var(--accent);
  color: var(--on-accent);
  font-weight: 550;
  box-shadow: none;
}
.ds-btn-primary:hover{ filter: brightness(1.07); }
.ds-btn-primary:disabled{ opacity: .45; cursor: not-allowed; filter: none; }
.ds-lane-foot .ds-btn{ padding: 9px 16px; font-size: 14px; }
.ds-btn-pair .ds-btn{
  border: 0;
  border-radius: 0;
  box-shadow: none;
}
.ds-btn-pair .ds-btn + .ds-btn{ border-inline-start: 0.5px solid var(--line); }
.ds-btn-pair .ds-btn:hover{ background: var(--surface-2); }
.ds-btn.ds-is-busy{
  position: relative;
  color: transparent !important;
  pointer-events: none;
}
.ds-btn.ds-is-busy::after{
  content: "";
  position: absolute;
  top: 50%; left: 50%;
  width: 13px; height: 13px;
  margin: -6.5px 0 0 -6.5px;
  border-radius: 50%;
  border: 0.5px solid var(--line);
  border-top-color: var(--accent);
  animation: none;
}
.ds-btn-primary.ds-is-busy::after{ border-color: var(--black-a5); border-top-color: #fdfdff; }
.ds-btn:active{ transform: translateY(.5px) scale(.995); }
.ds-btn.ds-is-busy::after{ animation-duration: 2s; }
